UPDATE lessons SET title='Year 3, Week 22, Lesson 1: Teamwork and roles in a team', data=json_patch(data,'{"child_mission":"Teams work best when each person has a role and everyone communicates. Roles can include attacker, defender, goalkeeper, captain, scorer or encourager. Good teammates use clear calls such as names, ''Pass!'' and ''Mine!'', encourage each other, share the ball and accept decisions fairly. Roles can rotate so everyone can try them.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same idea to a new game or situation, then compare two choices for safety and inclusion.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nA team keeps losing the ball because everyone chases it. Suggest two roles or rules that could help.\n\nFEEDBACK\nGive some players set positions (defender and attacker) and add a rule that only two players chase the ball. Calling ''Mine!'' avoids collisions. Clear roles share the work and help communication.\n\nWATCH FOR\nBelieving the best player should do everything. Passing and using every role makes the whole team stronger.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nPlan a team of four with four roles, three communication calls and a rotation rule. Draw a diagram of positions. Use the plan in a game with family and record what worked and what to change.\n\nWrite a short reflection naming one choice you changed and why. Any movement is optional, adult-supervised and can be done in a gentler way or described instead.","interactive_activities":null,"learning_area":"PDHPE","learning_intention":"Teams work best when each person has a role and everyone communicates. Roles can include attacker, defender, goalkeeper, captain, scorer or encourager. Good teammates use clear calls such as names, ''Pass!'' and ''Mine!'', encourage each other, share the ball and accept decisions fairly. Roles can rotate so everyone can try them.","lesson_number":1,"lesson_role":"Learn and discuss","materials":["Paper or typed answer space","Pencil","Clear, safe movement space with an adult nearby for any physical activity","Optional: soft ball, cushion or water bottle"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["PH2-MSP-01"],"parent_notes":"Parent: Marking guidance for the independent task: Plan a team of four with four roles, three communication calls and a rotation rule. Draw a diagram of positions. Use the plan in a game with family and record what worked and what to change. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: original example using teamwork on new material; names a specific word, source or choice and explains its effect.\n\nParent: Written model 2: Sample error: Believing the best player should do everything.. Correction: Give some players set positions (defender and attacker) and add a rule that only two players chase the ball.. Why it helps the audience is stated.\n\nParent: Likely misconception: Believing the best player should do everything. Passing and using every role makes the whole team stronger. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Produce a fresh example demonstrating teamwork on new material (not the worked model). Explain the particular words, sources or choices that make it work.\n\nParent: Short-answer focus 2: Name one likely error with teamwork, correct it, and explain why the correction helps a reader or audience.\n\nParent: Marking notes: Accept original work about teamwork with a specific supporting detail. Reject copied model wording with no new material. / Accept a misconception, a correction, and a purpose-linked reason for teamwork. Reject corrections that do not change the inaccurate idea..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":2,"explanation":"This matches the taught method for teamwork. The other choices miss a key step or use a common mistake.","options":["A claim that names no evidence from the lesson material","A method that skips the key step taught in this lesson","Give some players set positions (defender and attacker) and add a rule that only two players chase the ball","Believing the best player should do everything"],"question":"A team keeps losing the ball because everyone chases it. Suggest two roles or rules that could help. Which response is most accurate?","type":"multiple_choice"},{"correct_index":0,"explanation":"This is the misconception to avoid for teamwork; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["Believing the best player should do everything","Teams work best when each person has a role and everyone communicates","Give some players set positions (defender and attacker) and add a rule that only two players chase the ball","Careful use of team roles and explain why it matters with clear evidence"],"question":"Which statement is a common mistake when working with teamwork?","type":"multiple_choice"},{"correct_index":3,"explanation":"Understanding is shown by new evidence and a named team roles and explain why it matters, not by copying the model. The other choices miss a key step or use a common mistake.","options":["Repeat the worked example wording with no new evidence","Believing the best player should do everything","Name team roles and explain why it matters only, without linking it to teamwork","Apply teamwork to new material and name the team roles and explain why it matters used"],"question":"Which response best applies teamwork with new evidence?","type":"multiple_choice"},{"correct_index":3,"explanation":"The stronger choice uses safe, healthy or respectful choices appropriately for this lesson on teamwork. The other choices miss a key step or use a common mistake.","options":["Choose the fastest option even when it ignores safety","Use a put-down and call it honesty","Believing the best player should do everything","Give some players set positions (defender and attacker) and add a rule that only two players chase the ball"],"question":"Which response best uses safe, healthy or respectful choices for teamwork?","type":"multiple_choice"},{"correct_index":1,"explanation":"Strong answers name specific evidence and what it shows. The other choices miss a key step or use a common mistake.","options":["Believing the best player should do everything","Name a body cue, safety rule or wellbeing strategy and say how it helps with teamwork","Choose the fastest option even when it ignores safety","Use a put-down and call it honesty"],"question":"Which evidence move best supports a claim about teamwork?","type":"multiple_choice"},{"correct_index":1,"explanation":"The stronger choice matches the taught idea (Teams work best when each person has a role and everyone communicates.) with concrete detail. The other choices miss a key step or use a common mistake.","options":["Use a put-down and call it honesty","Example: a team of four has a captain who organises positions, two attackers who pass often, one defender who calls","Believing the best player should do everything","Choose the fastest option even when it ignores safety"],"question":"Which choice best applies this lesson idea about teamwork?","type":"multiple_choice"},{"correct_index":0,"explanation":"Accuracy means checking evidence and honouring limits or protocols. The other choices miss a key step or use a common mistake.","options":["Check safety and fairness, include others, and explain the healthier choice","Invent missing details to make the answer sound complete","Ignore safety or cultural protocols to finish faster","Treat every claim as equally reliable without checking a source or cue"],"question":"Which action keeps safe, healthy or respectful choices accurate for teamwork?","type":"multiple_choice"},{"correct_index":3,"explanation":"Independence requires a new example that still uses the taught skill. The other choices miss a key step or use a common mistake.","options":["Retype the worked example with no new example","Believing the best player should do everything","Name team roles and explain why it matters only, with no linked example","Plan a team of four with four roles, three communication calls and a rotation rule"],"question":"Which independent response best applies teamwork to new material?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Accept original work about teamwork with a specific supporting detail. Reject copied model wording with no new material.","question":"Produce a fresh example demonstrating teamwork on new material (not the worked model). Explain the particular words, sources or choices that make it work.","sample_answer":"Sample: original example using teamwork on new material; names a specific word, source or choice and explains its effect.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Accept a misconception, a correction, and a purpose-linked reason for teamwork. Reject corrections that do not change the inaccurate idea.","question":"Name one likely error with teamwork, correct it, and explain why the correction helps a reader or audience.","sample_answer":"Sample error: Believing the best player should do everything.. Correction: Give some players set positions (defender and attacker) and add a rule that only two players chase the ball.. Why it helps the audience is stated.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent evidence and reflection, with reasons where requested. Share only what you feel comfortable sharing.","review_status":"unreviewed","seed_key":"s2-pdhpe-y3-w22-l1","sort_activity":null,"source_note":"Proposed Stage 2 NESA PDHPE alignment using catalogue outcome codes (PH2-*); content-point mapping remains pending human review. Physical activities are optional, adult-supervised and adaptable; no child is required to share personal details.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise teamwork.","Read the mission before you start moving or deciding.","Keep your own safety and everyone''s inclusion in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your reasons with the feedback.","Adjust anything that does not keep everyone safe and included."],"learn":["Study how the first demonstration is built.","Point to the cue or rule that carries the idea.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore safety, consent or inclusion.","Prefer a reasoned, respectful choice over one that merely looks fun."],"submit":["Confirm that your reasons and reflection are both present.","Proofread names, steps and safety words.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked example.","Name one exact cue, rule or choice before you decide.","Think through the small prompt before opening the comparison."],"teach1":["Return to the example and list the key cues.","Say what each cue does for safety, health or friendship.","A final label alone is weaker than a stated reason."],"teach2":["Compare an unsafe or unkind choice with a better one.","Change the choice or strategy, not only the words.","Name the mistake you are repairing."],"teach3":["Choose a fresh place, game or situation that still uses the same skill.","Write one reason in your own words.","Do not retype the worked example as your answer."],"write":["Follow every part of the independent instructions.","Include original reasons and a short reflection.","Save work that shows the skill in a new situation."]},"subject":"Movement Skill and Performance","success_criteria":["I can use teamwork with a specific example from this lesson.","I can identify team roles and explain why it matters.","I can practise communication calls independently on a new prompt.","I can notice rotating roles needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":0,"explanation":"Teams work best when each person has a role and everyone communicates.","options":["Teams work best when each person has a role and everyone communicates","A choice unrelated to safety, health or respect","An answer copied without understanding","A guess with no reason"],"question":"Which choice best applies this lesson idea about teamwork with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nExample: a team of four has a captain who organises positions, two attackers who pass often, one defender who calls ''Mine!'' and an encourager who gives praise. They rotate roles each round. Result: more passes, fewer arguments, and each player scores a point.\n\nTRY FIRST\nA team keeps losing the ball because everyone chases it. Suggest two roles or rules that could help.\n\nFEEDBACK\nGive some players set positions (defender and attacker) and add a rule that only two players chase the ball. Calling ''Mine!'' avoids collisions. Clear roles share the work and help communication.","explain":"Teams work best when each person has a role and everyone communicates. Roles can include attacker, defender, goalkeeper, captain, scorer or encourager. Good teammates use clear calls such as names, ''Pass!'' and ''Mine!'', encourage each other, share the ball and accept decisions fairly. Roles can rotate so everyone can try them.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Believing the best player should do everything. Passing and using every role makes the whole team stronger. Change the choice or strategy, not just the wording.","title":"Understand and demonstrate","visual":[{"alt":"Team roles and calls.","caption":"Everyone has a role.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Roles</text><text x=\"28\" y=\"78\">captain, attacker, defender</text><text x=\"358\" y=\"42\">Calls</text><text x=\"358\" y=\"78\">Mine, Pass, Here</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which cue or rule matters most.","who":"pip"},{"text":"Name the cues, rules or choices that keep everyone safe and included before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this example: Example: a team of four has a captain who organises positions, two attackers who pass often, one defender who calls ''Min Then write your own reasons.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which cue or rule matters most.\nJuno: Name the cues, rules or choices that keep everyone safe and included before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this example: Example: a team of four has a captain who organises positions, two attackers who pass often, one defender who calls ''Min Then write your own reasons."}}]},{"check":{"correct_index":0,"explanation":"Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or others.","options":["Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or","A choice unrelated to safety, health or respect","An answer copied without understanding","A guess with no reason"],"question":"Which choice best applies this lesson idea about teamwork with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nExample: a team of four has a captain who organises positions, two attackers who pass often, one defender who calls ''Mine!'' and an encourager who gives praise. They rotate roles each round. Result: more passes, fewer arguments, and each player scores a point. Look at each cue, rule or choice that carries the idea.\n\nTRY FIRST\nList the key cues, rules or choices from the example and say what each one does for safety, health or relationships.\n\nFEEDBACK\nThe most useful reasoning names the cue, rule or strategy and the reason it helps, not only a label such as \"good\".","explain":"Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or others.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Writing only a final label without a reason does not show PDHPE thinking. Change the choice or strategy, not just the wording.","title":"Show the reasoning","visual":[{"alt":"Chasing and positions.","caption":"Spread the work.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Everyone chases</text><text x=\"28\" y=\"78\">collisions</text><text x=\"358\" y=\"42\">Set positions</text><text x=\"358\" y=\"78\">space and passes</text></g></svg>"}]},{"check":{"correct_index":0,"explanation":"Use an intentionally unsafe or unhelpful choice as a comparison.","options":["Use an intentionally unsafe or unhelpful choice as a comparison","A choice unrelated to safety, health or respect","An answer copied without understanding","A guess with no reason"],"question":"Which choice best applies this lesson idea about teamwork with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nBelieving the best player should do everything. Passing and using every role makes the whole team stronger. Here is a more helpful example: Example: a team of four has a captain who organises positions, two attackers who pass often, one defender who calls ''Mine!'' and an encourager who gives praise. They rotate roles each round. Result: more passes, fewer arguments, and each player scores a point.\n\nTRY FIRST\nDescribe why the warned-against choice does not work, then write a safer, kinder or healthier choice with a reason.\n\nFEEDBACK\nGive some players set positions (defender and attacker) and add a rule that only two players chase the ball. Calling ''Mine!'' avoids collisions. Clear roles share the work and help communication.","explain":"Use an intentionally unsafe or unhelpful choice as a comparison. Name the specific PDHPE error, then show the safer or more respectful choice.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Changing the wording without changing the choice does not fix the error. Believing the best player should do everything. Passing and using every role makes the whole team stronger. Change the choice or strategy, not just the wording.","title":"Test a misconception"},{"check":{"correct_index":1,"explanation":"Use the same PDHPE idea in a new place, game or situation, not a copy of the example.","options":["An answer copied without understanding","Use the same PDHPE idea in a new place, game or situation, not a copy of the example","A guess with no reason","A choice unrelated to safety, health or respect"],"question":"Which choice best applies this lesson idea about teamwork with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nTeams work best when each person has a role and everyone communicates. Roles can include attacker, defender, goalkeeper, captain, scorer or encourager. Good teammates use clear calls such as names, ''Pass!'' and ''Mine!'', encourage each other, share the ball and accept decisions fairly. Roles can rotate so everyone can try them. Now choose a different situation to show you can transfer the idea.\n\nTRY FIRST\nDescribe or practise one fresh situation that uses the same skill and write a short reason for your choice.\n\nFEEDBACK\nThe new situation should use the same PDHPE idea as the example, but happen in a different place or with different people.","explain":"Use the same PDHPE idea in a new place, game or situation, not a copy of the example. Review safety, fairness and inclusion.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Repeating the worked example cannot show transfer to a new situation. Change the choice or strategy, not just the wording.","title":"Transfer to a new situation"}],"title":"Year 3, Week 22, Lesson 1: Teamwork and roles in a team","unit_number":5,"unit_title":"Games and sports: teamwork and fair play","week":22,"week_in_unit":2,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nExample: a team of four has a captain who organises positions, two attackers who pass often, one defender who calls ''Mine!'' and an encourager who gives praise. They rotate roles each round. Result: more passes, fewer arguments, and each player scores a point.\n\nWrite what makes this example safe, healthy or respectful, naming the cues, rules or choices used.","worked_visuals":[{"alt":"Team roles and calls.","caption":"Everyone has a role.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Roles</text><text x=\"28\" y=\"78\">captain, attacker, defender</text><text x=\"358\" y=\"42\">Calls</text><text x=\"358\" y=\"78\">Mine, Pass, Here</text></g></svg>"},{"alt":"Chasing and positions.","caption":"Spread the work.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Everyone chases</text><text x=\"28\" y=\"78\">collisions</text><text x=\"358\" y=\"42\">Set positions</text><text x=\"358\" y=\"78\">space and passes</text></g></svg>"}],"year_level":"Year 3"}') WHERE seed_key='s2-pdhpe-y3-w22-l1' AND family_id IS NULL;
